// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2011, "10-11", [{"author":"М. Тюренкова","question":"Какие из этих слов обозначают человека: 1) <em>намордник</em>, 2) <em>наследник</em>, 3) <em>подзатыльник</em>, 4) <em>подкаблучник</em>, 5) <em>подлокотник</em>?","choices":["только 2","1 и 2","2 и 4","3 и 5","никакие."],"key":"В","review":["Названия людей и предметов","Проверь, кто может выполнять действие или обладать чертой характера, а какие слова называют вещи.","«Наследник» получает наследство, «подкаблучник» — человек, подчинённый супруге. Намордник и подлокотник — предметы, подзатыльник — удар."]},{"author":"Н. Валеева","question":"Какое из этих устойчивых словосочетаний по смыслу устроено не так, как остальные?","choices":["<em>впасть в бешенство</em>","<em>впасть в уныние</em>","<em>впасть в ярость</em>","<em>впасть в немилость</em>","<em>впасть в отчаяние</em>."],"key":"Г","review":["Состояние и отношение","Четыре оборота называют чувства человека. Ищи случай, в котором меняется отношение других людей к нему.","«Впасть в немилость» — лишиться чьей-либо благосклонности. Бешенство, уныние, ярость и отчаяние обозначают состояния самого человека."]},{"author":"Б. Иомдин","question":"Какой из этих глаголов относится к совершенному виду и при этом не содержит приставки?","choices":["<em>сдать</em>","<em>сжать</em>","<em>слать</em>","<em>спать</em>","<em>стать</em>."],"key":"Д","review":["Вид и приставка","Поставь вопрос «что сделать?» и проверь, отделяется ли первая буква как приставка, например в «с-дать».","«Стать» — глагол совершенного вида с корнем «ста-». «Сдать» и «сжать» содержат приставку, «слать» и «спать» несовершенного вида."]},{"author":"И. Иткин","question":"Дано предложение: <em>Одним словом(,) закончить это стихотворение невозможно</em>. Что можно сказать о постановке запятой перед <em>закончить</em>?","choices":["правилен только вариант с запятой","правилен только вариант без запятой","оба варианта правильны и одинаковы по смыслу","оба варианта правильны, но различаются по смыслу","предложение неправильно в обоих случаях."],"key":"Г","review":["Запятая и смысл","Прочитай «одним словом» как вводный оборот со значением «короче говоря» и как ответ на вопрос «чем закончить?».","С запятой говорящий подводит итог: закончить стихотворение невозможно. Без запятой говорится, что его невозможно закончить одним словом."]},{"author":"И. Рубанов","question":"5 апреля 1941 года семнадцатилетний король Югославии Пётр подписал Договор о дружбе и ненападении между Югославией и СССР. Тогда же родилась такая шутка: <em>Почему югославский король решил подружиться с СССР? Потому что он ... и молод</em>. Какое слово мы заменили многоточием?","choices":["<em>македонец</em>","<em>серб</em>","<em>словенец</em>","<em>хорват</em>","<em>черногорец</em>."],"key":"Б","review":["Шутка о договоре","Сопоставь слово «молод» со звучащим похоже словом из советской эмблемы. Вспомни название второй её части.","«Серб и молод» звучит почти как «серп и молот». В шутке обыграно сочетание, связанное с символикой СССР."]},{"author":"П. Аркадьев","question":"Одно из стихотворений О. Э. Мандельштама называется «Веницейская жизнь». А как оно должно было бы называться в соответствии с современными языковыми нормами?","choices":["<em>Венетийская жизнь</em>","<em>Веницианская жизнь</em>","<em>Венецианская жизнь</em>","<em>Винецианская жизнь</em>","<em>Венецейская жизнь</em>."],"key":"В","review":["Название у Мандельштама","Образуй прилагательное от «Венеция». Вспомни, как называют жителя этого города.","Сегодня употребляют «венецианец» и «венецианский». По современной норме заглавие звучало бы «Венецианская жизнь»."]},{"author":"Б. Иомдин","question":"Четыре из пяти данных ниже выражений, нередко употребляемых журналистами, обладают некоторым общим свойством — таким, что хорошие редакторы обычно их исправляют. Пятое выражение этим свойством не обладает. Какое?","choices":["<em>взаимоотношения друг с другом</em>","<em>в течение долгого времени</em>","<em>госпитализация в больницу</em>","<em>круглые сутки напролёт</em>","<em>бесплатный подарок</em>."],"key":"Б","review":["Слова с повтором смысла","Убери из каждого оборота одно слово и проверь, исчезает ли часть смысла. Например, «госпитализация» уже предполагает больницу.","«В течение долгого времени» сообщает длительность, и «долгого» её уточняет. В остальных выражениях одно уточнение повторяет уже выраженный смысл."]},{"author":"Н. Добрушина","question":"Вот отрывок из поэмы К. Ф. Рылеева «Войнаровский»:\n<em>Всё для пришельца было ново:\nПрироды дикой красота,\nКлимат жестокий и суровый\nИ диких нравов простота.</em>\nКакое слово в этом отрывке произносится не с таким ударением, с каким его принято произносить сейчас?","choices":["<em>пришельца</em>","<em>дикой</em>","<em>климат</em>","<em>жестокий</em>","<em>нравов</em>."],"key":"В","review":["Ударение у Рылеева","Прочти строфу в ритме ямба. В начале третьей строки сильная позиция приходится на второй слог.","У Рылеева стих требует «клима́т». В современной норме ударение на первом слоге — «кли́мат»."]},{"author":"Методкомиссия","question":"Если набрать на компьютере слово <em>надуться</em> без мягкого знака, компьютер укажет, что в слове есть ошибка. В каком из этих слов, если написать их без мягкого знака, компьютер тоже отметит ошибку?","choices":["<em>хмуриться</em>","<em>морщиться</em>","<em>бояться</em>","<em>смеяться</em>","<em>улыбнуться</em>."],"key":"Г","review":["Форма глагола без «ь»","Убери мягкий знак и проверь, есть ли в языке такая личная форма. Выбери к ней подлежащее «он» или «они».","Есть «хмурится», «морщится», «боятся», «улыбнутся». От «смеяться» современная личная форма «смеются», поэтому «смеятся» будет ошибкой."]},{"author":"И. Иткин","question":"В своей статье, посвящённой употреблению одного устойчивого выражения, профессор Мышкин приводит несколько примеров из литературных произведений. Какой пример попал в статью профессора Мышкина по ошибке?","choices":["<em>И он не сделался поэтом, Не умер, не сошёл с ума.</em> (А. С. Пушкин, «Евгений Онегин»)","<em>Обещаю тебе, что ты с ума сойдёшь, и это непременно, и так уж тебе какие-то чертенята, я слышал, показывались...</em> (В. Ф. Одоевский, «Косморама»)","<em>Не ответила Дуня, но с тех пор Пётр Степаныч не сходил у неё с ума.</em> (П. И. Мельников-Печерский, «На горах»)","<em>Уйти в бега, сойти с ума Теперь уж поздно для меня.</em> (А. М. Городницкий, «На материк»)","<em>Если бы мы с ума сошли, то не оба сразу. С ума по отдельности сходят.</em> (Э. Н. Успенский, «Дядя Фёдор, пёс и кот»)."],"key":"В","review":["Оборот со словом «ум»","Определи, кто теряет рассудок, а кто просто остаётся в мыслях другого человека.","У Мельникова-Печерского «не сходил у неё с ума» значит, что Дуня постоянно о нём помнила. Остальные авторы употребляют оборот в значении «потерять рассудок»."]},{"author":"Е. Маркасова и методкомиссия","question":"Найдите все причастия от глагола <em>рисковать</em>.","choices":["<em>рискованный</em>","<em>рисковавший</em>","<em>рисковавший</em>, <em>рискованный</em>","<em>рискующий</em>, <em>рисковавший</em>","<em>рискующий</em>, <em>рисковавший</em>, <em>рискованный</em>."],"key":"Г","review":["Причастия от глагола","Проверь две формы по вопросам «кто рискует?» и «кто рисковал?». Отдельно оцени, обозначает ли «рискованный» чьё-то действие.","«Рискующий» — действительное причастие настоящего времени, «рисковавший» — прошедшего. «Рискованный» обозначает признак и является прилагательным."]},{"author":"Н. Валеева","question":"Какое из этих кушаний названо не по действию, связанному с его приготовлением?","choices":["<em>варенье</em>","<em>запеканка</em>","<em>отбивная</em>","<em>сливки</em>","<em>похлёбка</em>."],"key":"Д","review":["Кушанья и способы готовки","Восстанови действия, стоящие за названиями: варить, запекать, отбивать и сливать.","«Похлёбка» связана с «хлебать», то есть с употреблением еды. Другие названия указывают на действие при приготовлении."]},{"author":"А. Пиперски","question":"Даны названия нескольких российских футбольных клубов: «Амкар» (Пермь), «Волга» (Нижний Новгород), «Краснодар» (Краснодар), «Кубань» (Краснодар), «Нижний Новгород» (Нижний Новгород), «Салют» (Белгород). Игроков каких двух из этих команд в спортивной прессе иногда называют словом «горожане»?","choices":["«Волга» и «Салют»","«Краснодар» и «Кубань»","«Салют» и «Амкар»","«Нижний Новгород» и «Волга»","«Краснодар» и «Нижний Новгород»."],"key":"Д","review":["Прозвища футбольных команд","Сравни названия клубов с городами, в которых они играют. Два клуба названы непосредственно по городу.","«Краснодар» и «Нижний Новгород» носят названия своих городов. Это объясняет прозвище «горожане» для их игроков."]},{"author":"О. Подлесская","question":"В какой фразе выделенное слово представляет собой старинное название буквы <em>Ф</em>?","choices":["<em>Прикидываясь моей добычей, этот враг хочет меня погубить, но я разгадал его <strong>фортель</strong>, и придёт время, когда я с ним посчитаюсь</em>. (И. Ф. Анненский).","<em>Рабочий, что первый завел речь о расчёте, картуз надел и <strong>фертом</strong> подбоченился.</em> (П. И. Мельников-Печерский).","<em>Я сделал <strong>финт</strong> левой рукой, а ударил правой, и противник попался на эту простую уловку</em>. (В. П. Михайлов).","<em>Три прохожих офицера стали на Невском проспекте во <strong>фрунт</strong></em>. (Ю. Н. Тынянов).","— <em>Застрекотала стрекоза, ходит <strong>франтом</strong>, сапоги с рантом, — сказал ей Самсон по-русски</em>. (Ю. Н. Тынянов)."],"key":"Б","review":["Старинная буква","Вспомни старое название буквы Ф и представь, какую позу могут напоминать её округлые части по сторонам.","Ф называли «ферт». «Подбоченился фертом» значит поставил руки на пояс и развёл локти, напоминая форму буквы."]},{"author":"Б. Иомдин","question":"<em>Человек человеку волк, а кенгуру кенгуру кенгуру</em>. Слова в каких падежах встречаются в этой фразе?","choices":["Два раза в именительном, два раза в винительном и два раза в дательном.","Четыре раза в именительном, один раз в винительном и один раз в дательном<em>.</em>","Четыре раза в именительном, один раз в родительном и один раз в дательном.","Четыре раза в именительном и два раза в дательном.","Пять раз в именительном и один раз в дательном."],"key":"Г","review":["Падежи в пословичной фразе","Во второй части повтори грамматическую схему первой. Вопросы к словам сохраняются, хотя слово «кенгуру» не меняется.","В каждой половине два именительных — подлежащее и именная часть сказуемого. Слово «человеку» и второе «кенгуру» отвечают на «кому?». Всего четыре именительных и два дательных."]},{"author":"Н. Добрушина","question":"Придаточные предложения играют роль разных членов предложения: определений, дополнений, обстоятельств, подлежащих. Разделите следующие предложения на две группы в зависимости от того, какую роль играют в них придаточные.\n1) Полмесяца не хватало, чтобы ремонт закончился.\n2) Для полного сходства не хватало, чтобы был подбит левый глаз.\n3) Денег не хватало, чтобы перегородить проход.\n4) Только ещё не хватало, чтобы в дом какую-нибудь заразу притащить.\n5) Иногда не хватало сил, чтобы добраться до дома.","choices":["1,2 и 3,4,5","1,3 и 2,4,5","1,3,4 и 2,5","1,2,5 и 3,4","1,3,5 и 2,4."],"key":"Д","review":["Придаточные с «чтобы»","Проверь, где не хватает времени, денег или сил для цели и где придаточное само называет то, чего не хватает.","В примерах 1, 3 и 5 придаточные отвечают на «для чего?». В 2 и 4 придаточные отвечают на «чего не хватало?». Получаются группы 1, 3, 5 и 2, 4."]},{"author":"Б. Иомдин","question":"К четырём из данных ниже слов можно добавить в начале один и тот же слог и получить новое слово с близким значением. Найдите пятое, с которым так сделать не получится.","choices":["<em>хвалиться</em>","<em>хвастаться</em>","<em>бахнуть</em>","<em>рельеф</em>","<em>лясы.</em>"],"key":"Б","review":["Один слог в начале","Вспомни слово «бабахнуть». Отними от него «бахнуть» и попробуй прибавить тот же слог к другим словам.","«Ба-» даёт «бахвалиться», «бабахнуть», «барельеф» и «балясы». Слова «бахвастаться» нет."]},{"author":"Б. Иомдин","question":"Сын-студент пишет отцу домой: <em>Деньги _____ — _____ деньги</em>. Что мы дважды пропустили в этом анекдоте?","choices":["<em>пошли</em>","<em>прошли</em>","<em>вышли</em>","<em>нашли</em>","<em>ушли</em>."],"key":"В","review":["Два одинаковых написания","В первой части сын сообщает, что средства кончились. Во второй ему надо попросить отца прислать их снова.","Получается «Деньги вы́шли — вышли́ деньги». Первое слово значит «кончились», второе — просьба «отправь»."]},{"author":"И. Рубанов","question":"Вот заголовки четырёх документов из папки секретаря директора. Какой из них построен заведомо неправильно?","choices":["<em>Список приглашённых гостей на обед</em>.","<em>Список поданных заявок на ремонт</em>.","<em>Список заказанных билетов на самолёт</em>.","<em>Список срочных документов на подпись</em>.","Все заголовки (А)–(Г) построены правильно."],"key":"А","review":["Слова в заголовке","Проверь, к какому слову относится оборот после существительного. Например, «на самолёт» может относиться прямо к «билеты».","Гостей приглашают «на обед». Нужен цельный оборот «список приглашённых на обед гостей». Сочетание «гости на обед» не образует такого названия."]},{"author":"Л. Фёдорова","question":"В словаре В. И. Даля (<em>Толковый словарь живого великорусского языка</em>), изданном в середине XIX века, есть слово <em>светопись.</em> Какое слово сейчас употребляется вместо него?","choices":["<em>стенография</em>","<em>силуэт</em>","<em>иконопись</em>","<em>фотография</em>","<em>живопись</em>."],"key":"Г","review":["Старое название изображения","Представь способ получать изображение, регистрируя свет, а не рисуя его кистью.","«Светопись» — старое русское название фотографии. Слово буквально передаёт идею записи светом."]},{"author":"И. Рубанов","question":"Дана фраза: <em>В передаче принимает участие Иван Петров, руководитель организации «Общество реставраторов», ... восстанавливать архитектурные памятники</em>. Какие из словосочетаний 1) <em>который призывает</em>, 2) <em>которая призывает</em>, 3) <em>которое призывает</em>, 4) <em>которые призывают</em> можно вставить в неё вместо многоточия?","choices":["только 1","только 2","только 1 и 2","все, кроме 4","все."],"key":"В","review":["Согласование в длинной фразе","Определи, к кому или чему может относиться продолжение. Смотри на главные слова вне кавычек.","Можно «который призывает» об Иване Петрове или «которая призывает» об организации. Слова внутри её названия не задают согласование внешнему придаточному."]},{"author":"П. Аркадьев","question":"При образовании какого из данных уменьшительных слов происходит чередование, не происходящее при образовании других слов?","choices":["<em>бутылка</em>","<em>долька</em>","<em>стрелка</em>","<em>кобылка</em>","<em>медалька</em>."],"key":"А","review":["Чередование у уменьшительных","Восстанови основы: «бутыль», «доля», «стрела», «кобыла», «медаль». Проверь, где меняется мягкость «л».","У «бутыль» конечное «л» мягкое, а в «бутылка» становится твёрдым. В остальных парах твёрдость или мягкость основы сохраняется."]},{"author":"А. Сомин","question":"Даны названия частей речи на белорусском языке: <em>прыназоўнік, выклічнік, назоўнік, прыметнік, дзеяслоў</em>. Как они называются по-русски? (Буква <em>ў</em> обозначает звук, средний между <em>в</em> и <em>у</em>.)","choices":["имя прилагательное, имя существительное, междометие, предлог, глагол","имя существительное, междометие, имя прилагательное, предлог, глагол","предлог, глагол, имя существительное, имя прилагательное, междометие","имя прилагательное, глагол, имя существительное, предлог, междометие","предлог, междометие, имя существительное, имя прилагательное, глагол."],"key":"Д","review":["Части речи по-белорусски","Узнай «назоў» как название, «кліч» как восклицание и «дзея» как действие. Затем сопоставь «прыметнік» с признаком.","Порядок переводов: предлог, междометие, имя существительное, имя прилагательное, глагол."]},{"author":"И. Иткин","question":"Какое из этих слов исторически не родственно остальным?","choices":["<em>пряжа</em>","<em>пряжка</em>","<em>упряжка</em>","<em>напряжение</em>","<em>распрягать</em>."],"key":"А","review":["Корни двух семейств","Проверь, что связано с прядением нити, а что с упряжью, натяжением или запряганием.","«Пряжа» происходит от глагола «прясть». «Пряжка», «упряжка», «напряжение» и «распрягать» исторически относятся к другому корню."]},{"author":"В. Черванёва","question":"<em>Вести</em>, <em>гвоздика</em>, <em>сорока</em>, ... . Каким словом нельзя продолжить этот список?","choices":["<em>вороной</em>","<em>пирогу</em>","<em>полка</em>","<em>страны</em>","<em>толку</em>."],"key":"Г","review":["Одинаковое написание","Попробуй дважды прочесть каждое слово, переставив ударение. Важно получить формы двух разных слов.","«Стра́ны» и «страны́» — формы одного слова «страна». В остальных случаях получаются формы разных слов: например, «по́лка» и «полка́» от «полк»."]},{"author":"Л. Фёдорова","question":"<em>Разыскивая тайник, он обошёл вдоль и поперёк дорожки парка, заметив заброшенную часовню, обошёл её вокруг и, отыскав между кустами жимолости ход внутрь, остановился рядом</em>. Сколько предлогов в данной выше фразе?","choices":["один","два","три","четыре","не меньше пяти."],"key":"А","review":["Предлоги в рассказе","Для каждого короткого слова проверь, вводит ли оно зависимое существительное, или обозначает место и направление само по себе.","«Между» вводит «кустами». «Вдоль и поперёк», «вокруг», «внутрь» и «рядом» описывают действия сами, поэтому здесь есть один предлог."]},{"author":"И. Иткин","question":"¬поведь. Сколько разных приставок можно подставить на место знака ¬?","choices":["ни одной","одну","две","три","четыре."],"key":"Д","review":["Приставки перед «поведь»","Добавляй части, знакомые по русским словам о наставлении, признании или ответе.","Получаются «исповедь», «проповедь», «заповедь» и «отповедь». Это четыре разные приставки."]},{"author":"Б. Иомдин","question":"Ниже дано пять названий главок из книги М. В. Панова о русской орфографии «И всё-таки она хорошая». Какая из них начинается так: «Есть одна профессия, которая требует, чтобы при чтении глаз охватывал все буквы, а не только общее очертание слова»?","choices":["«Читают газету»","«Промьшленность»","«О малограмотных»","«Писателям можно»","«Сплетение звуков»."],"key":"Б","review":["Чтение каждой буквы","Ищи заглавие, в котором легко не заметить ошибку именно потому, что глаз воспринимает слово целиком.","В «Промьшленность» вместо «ы» стоит «ь». Название иллюстрирует работу корректора, которому нужно замечать каждую букву."]},{"author":"А. Пиперски","question":"Название какой фигуры происходит от древнегреческого слова со значением ‘столик’?:","choices":["<em>квадрат</em>","<em>круг</em>","<em>овал</em>","<em>параллелограмм</em>","<em>трапеция</em>."],"key":"Д","review":["Происхождение названия фигуры","Сравни названия с греческим словом «трапеза». Оно могло называть стол и приём пищи за столом.","Древнегреческое «трапезион» обозначало столик. Из этого слова произошло название трапеции."]},{"author":"С. Бурлак и И. Иткин","question":"В одном древнерусском документе читаем:\n<em>А покаместа речка Непложа, ... и Борисоглебская владычня земля.</em>\nКак правильно заполнить пропуск?","choices":["<em>потудаместа</em>","<em>потаместа</em>","<em>по сю сторону</em>","<em>покудова</em>","<em>поелику</em>."],"key":"Б","review":["Граница старого владения","Сопоставь «покаместа» с современным «до какого места». Ищи ответное слово с похожим устройством.","«Потаместа» означает «до того места». Пара «покаместа — потаместа» указывает, где проходит граница названной земли."]}], {"year":2011,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2011.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
